import {KEY,validate,parseJSON,decodeFragment,merge,filterCatalog,randomIndex} from './core.js';
import bookmarklet from './bookmarklet-link.js';
import {setupIllustrationPreview} from './illustration-preview.js';
const $=id=>document.getElementById(id);
let pendingHash=location.hash.startsWith('#import=')?location.hash:null;
if(pendingHash)history.replaceState(null,'',location.pathname+location.search);
let catalog=[],illustrations={},progress=null,storageBroken=false,illustrationPreview=null;
const solved=()=>new Set(progress?.solvedIds||[]);
function notice(message,error=false){$('notice').textContent=message;$('notice').className=error?'error':'';$('notice').hidden=false;}
function loadProgress(){try{const raw=localStorage.getItem(KEY);if(raw){const original=JSON.parse(raw);progress={...validate(original),lastImportedAt:typeof original.lastImportedAt==='string'?original.lastImportedAt:null};}else progress=null;storageBroken=false;}catch{progress=null;storageBroken=true;notice('Saved progress could not be read. Browsing still works. Clear this site\'s browser data to reset corrupted data, or allow local storage if it is blocked.',true);}}
function options(){return {search:$('search').value,difficulty:$('difficulty').value,status:$('status').value};}
function node(tag,className,text){const element=document.createElement(tag);if(className)element.className=className;if(text!==undefined)element.textContent=text;return element;}
function problemLink(p){const a=node('a','problem-title',p.title);a.href=`https://leetcode.com/problems/${p.slug}/`;a.target='_blank';a.rel='noopener noreferrer';a.append(node('span','external','↗'));return a;}
function render(){illustrationPreview?.dismiss();const ids=solved(),rows=filterCatalog(catalog,ids,options()),eligible=rows.filter(p=>!ids.has(p.id));$('rows').replaceChildren();let group=null;
 for(const p of rows){const done=ids.has(p.id);if(group!==done){group=done;const r=node('tr','group'+(done?' solved-group':''));const cell=node('td','',done?'Already solved':'Ready to solve');cell.colSpan=5;r.append(cell);$('rows').append(r);}
 const row=node('tr',done?'solved-row':'');row.append(node('td','number',String(p.id)));const title=node('td');title.append(problemLink(p),node('p','summary',p.summary));row.append(title);const art=node('td','illustration-cell');const asset=illustrations[p.id];if(asset){const img=node('img','problem-illustration');img.src=asset.src;img.width=asset.width;img.height=asset.height;img.alt=asset.alt;img.loading='lazy';img.decoding='async';art.append(img);}row.append(art);const difficulty=node('td','difficulty-cell');difficulty.append(node('span','badge'+(p.difficulty==='Hard'?' hard':''),p.difficulty));row.append(difficulty);const status=node('td','state-cell');const state=node('span','state'+(done?' solved':''));state.append(node('span','state-icon',done?'✓':'○'),document.createTextNode(done?'Solved':'Unsolved'));status.append(state);row.append(status);$('rows').append(row);}
 const count=catalog.filter(p=>ids.has(p.id)).length;$('progress-label').textContent=`${count} / ${catalog.length}`;$('progress-bar').style.width=`${catalog.length?count/catalog.length*100:0}%`;$('rail-count').textContent=String(catalog.length);$('edition-count').textContent=String(catalog.length);$('progress-note').textContent=progress?`${catalog.length-count} left to explore. Synced as ${progress.username}.`:'Sync to see what you\'ve solved.';
 $('last-sync').textContent=progress?.lastImportedAt?'Last imported '+new Date(progress.lastImportedAt).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'No sync yet';
 $('result-count').textContent=`${rows.length} ${rows.length===1?'problem':'problems'} shown / ${catalog.length} reviewed`;$('empty').hidden=rows.length>0;$('pick').disabled=!eligible.length;$('pick').title=eligible.length?'Choose an unsolved problem':'No unsolved problems match your filters';$('clear').hidden=!($('search').value||$('difficulty').value!=='all'||$('status').value!=='all');
 $('backup-export').disabled=!progress;
}
function resetFilters(){$('search').value='';$('difficulty').value='all';$('status').value='all';$('picked').hidden=true;render();}
async function receive(incoming){try{if(storageBroken)throw Error('Saved progress is unavailable. Allow local storage or clear corrupt site data before importing.');loadProgress();if(storageBroken)throw Error('Saved progress is unavailable. Import was not saved.');
 let replace=false;if(progress&&progress.username.toLowerCase()!==incoming.username.toLowerCase()){
 $('account-message').textContent=`This export belongs to ${incoming.username}. Switching replaces ${progress.username}'s local progress. Export a backup first if you want to keep it.`;
 $('account-dialog').showModal();replace=await new Promise(resolve=>{const finish=value=>{$('account-dialog').close();resolve(value);};$('account-cancel').onclick=()=>finish(false);$('account-confirm').onclick=()=>finish(true);$('account-dialog').oncancel=()=>resolve(false);});if(!replace){notice('Account switch cancelled. Existing progress was kept.');return;}}
 const same=progress&&progress.username.toLowerCase()===incoming.username.toLowerCase();const before=new Set(same?progress.solvedIds:[]);const next=merge(progress,incoming,replace);localStorage.setItem(KEY,JSON.stringify(next));progress=next;const added=incoming.solvedIds.filter(id=>!before.has(id)).length;const count=catalog.filter(p=>next.solvedIds.includes(p.id)).length;$('picked').hidden=true;render();notice(`Progress imported for ${next.username}. ${added} newly recorded solved ${added===1?'problem':'problems'}; ${count} of ${catalog.length} on this shortlist solved.`);
 }catch(e){notice(e.name==='QuotaExceededError'||e.name==='SecurityError'?'Progress could not be saved. Allow local storage and try again. Existing progress was kept.':e.message,true);}}
async function importHash(){const hash=pendingHash||location.hash;pendingHash=null;if(!hash.startsWith('#import='))return;history.replaceState(null,'',location.pathname+location.search);try{await receive(decodeFragment(hash));}catch(e){notice(e.message,true);}}
$('bookmark').href=bookmarklet;$('bookmark').onclick=e=>{e.preventDefault();$('copy-state').textContent='Drag this to your bookmarks bar, then run the saved bookmark on LeetCode.';};
$('copy-bookmark').onclick=async()=>{try{await navigator.clipboard.writeText(bookmarklet);$('copy-state').textContent='Code copied. Paste it into a bookmark URL.';}catch{$('copy-state').textContent='Clipboard unavailable. Drag the bookmark button to your bookmarks bar instead.';}};
$('sync-open').onclick=()=>$('sync-dialog').showModal();$('method-open').onclick=()=>$('method-dialog').showModal();document.querySelectorAll('.close').forEach(button=>button.onclick=()=>button.closest('dialog').close());
for(const id of ['search','difficulty','status'])$(id).addEventListener(id==='search'?'input':'change',()=>{$('picked').hidden=true;render();});$('clear').onclick=resetFilters;$('empty-clear').onclick=resetFilters;
$('pick').onclick=()=>{const choices=filterCatalog(catalog,solved(),options()).filter(p=>!solved().has(p.id));try{const p=choices[randomIndex(choices.length)];const panel=$('picked');panel.replaceChildren();const dismiss=node('button','','Dismiss');dismiss.onclick=()=>panel.hidden=true;const heading=node('h2','',`${p.id}. ${p.title}`);const a=node('a','','Open on LeetCode ↗');a.href=`https://leetcode.com/problems/${p.slug}/`;a.target='_blank';a.rel='noopener noreferrer';panel.append(dismiss,node('div','selection-label','Your next problem'),heading,node('p','',p.summary),a);panel.hidden=false;}catch(e){notice(e.message);}};
$('backup-export').onclick=()=>{if(!progress)return;const text=JSON.stringify(validate(progress),null,2);const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=node('a');a.href=url;a.download='clearpick-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);};
$('file-import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>200000)throw Error('This export is too large. Maximum size is 200 KB.');const payload=parseJSON(await file.text());$('sync-dialog').close();await receive(payload);}catch(error){$('sync-dialog').close();notice(error.message,true);}finally{e.target.value='';}};
window.addEventListener('hashchange',importHash);window.addEventListener('storage',e=>{if(e.key===KEY){loadProgress();$('picked').hidden=true;render();}});
illustrationPreview=setupIllustrationPreview($('rows'));
loadProgress();
try{const response=await fetch('/catalog.json');if(!response.ok)throw Error('Catalog failed to load. Reload to try again.');const data=await response.json();const artResponse=await fetch('/illustrations.json');if(!artResponse.ok)throw Error('Illustrations failed to load. Reload to try again.');illustrations=await artResponse.json();catalog=data.problems;if(!Array.isArray(catalog)||!catalog.every(p=>Number.isSafeInteger(p.id)&&/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(p.slug)))throw Error('Catalog data is invalid.');$('coverage').textContent=data.coverage;render();await importHash();}catch(e){$('result-count').textContent='Catalog unavailable';$('pick').disabled=true;notice(e.message,true);}

const themeButton=$('theme-toggle');function applyTheme(theme){document.documentElement.dataset.theme=theme;themeButton.textContent=theme==='dark'?'Light theme':'Dark theme';themeButton.setAttribute('aria-label',theme==='dark'?'Switch to light theme':'Switch to dark theme');}let savedTheme='dark';try{savedTheme=localStorage.getItem('clearpick.theme')==='light'?'light':'dark';}catch{}applyTheme(savedTheme);themeButton.onclick=()=>{const next=document.documentElement.dataset.theme==='light'?'dark':'light';applyTheme(next);try{localStorage.setItem('clearpick.theme',next);}catch{}};
